// src/components/Dolar.js
import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Line } from 'react-chartjs-2';
import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
    Filler,
    Tooltip,
    Legend
} from 'chart.js';

// Registrar las escalas y componentes necesarios
ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Filler, Tooltip, Legend);

const Dolar = () => {
    const [data, setData] = useState([]); // Este estado almacenará los valores del dólar
    const [labels, setLabels] = useState([]); // Este estado almacenará las etiquetas (fechas/hora)
    const apiBaseUrl = 'http://localhost:8000'; // Cambia esto a la URL donde está tu API

    // Función para obtener el valor actual del dólar
    const fetchCurrentDollarValue = async () => {
        try {
            const response = await axios.get(`${apiBaseUrl}/dolar`); // Ajustar la URL
            const currentValue = response.data.price; // Ajusta según la estructura de la respuesta
            const currentTime = new Date().toLocaleTimeString(); // Obtener la hora actual

            // Actualiza el estado con el valor actual y la hora
            setData((prevData) => [...prevData, currentValue]); 
            setLabels((prevLabels) => [...prevLabels, currentTime]); 
        } catch (error) {
            console.error("Error al obtener el precio del dólar:", error);
        }
    };

    useEffect(() => {
        fetchCurrentDollarValue(); // Llama a la función al cargar el componente
        const intervalId = setInterval(() => {
            fetchCurrentDollarValue(); // Llama a la función cada 10 segundos
        }, 10000);

        // Limpia el intervalo al desmontar el componente
        return () => clearInterval(intervalId);
    }, []);

    const chartData = {
        labels: labels,
        datasets: [
            {
                label: 'Precio del Dólar (MXN)',
                data: data,
                borderColor: 'rgba(75,192,192,1)',
                backgroundColor: 'rgba(75,192,192,0.2)',
                fill: true,
            },
        ],
    };

    return (
        <div>
            <h1>Precio del Dólar en Tiempo Real</h1>
            {data.length > 0 ? (
                <Line data={chartData} />
            ) : (
                <p>Cargando datos...</p>
            )}
        </div>
    );
};

export default Dolar;
